refentry.refsect1:
&reftitle.parameters;
&mysqli.link.description;
string
La &string; à entourer de guillemets et à échapper.
Les caractères encodés sont NUL (ASCII 0), \n, \r, \, ', ", et CTRLZ. Si le mode SQL NO_BACKSLASH_ESCAPES est activé sur la connexion, seul ' est encodé, en le doublant.

  &reftitle.examples;

   Exemple avec mysqli::quote_string
   &style.oop;


<?php

mysqli_report(MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT);
$mysqli = new mysqli("localhost", "my_user", "my_password", "world");

$city = "'s-Hertogenbosch";

/* Cette requête avec $city entouré de guillemets fonctionnera */
$query = sprintf("SELECT CountryCode FROM City WHERE name=%s", $mysqli->quote_string($city));
$result = $mysqli->query($query);
printf("Select a retourné %d lignes.\n", $result->num_rows);

/* Cette requête échouera, car $city n'a pas été entouré de guillemets ni échappé */
$query = sprintf("SELECT CountryCode FROM City WHERE name='%s'", $city);
$result = $mysqli->query($query);


   &style.procedural;


<?php

mysqli_report(MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT);
$mysqli = mysqli_connect("localhost", "my_user", "my_password", "world");

$city = "'s-Hertogenbosch";

/* Cette requête avec $city entouré de guillemets fonctionnera */
$query = sprintf("SELECT CountryCode FROM City WHERE name=%s", mysqli_quote_string($mysqli, $city));
$result = mysqli_query($mysqli, $query);
printf("Select a retourné %d lignes.\n", mysqli_num_rows($result));

/* Cette requête échouera, car $city n'a pas été entouré de guillemets ni échappé */
$query = sprintf("SELECT CountryCode FROM City WHERE name='%s'", $city);
$result = mysqli_query($mysqli, $query);


